export function ImageSlider({
  dotStyle = "{{dotStyle}}",
  accent = "{{accent}}",
  showArrows = {{showArrows}},
  radius = {{radius}},
}) {
  const slides = [
    { fill: "#A8E6C1", alt: "Slide 1: pale circle on mint" },
    { fill: "#BFD9F2", alt: "Slide 2: pale circle on sky blue" },
    { fill: "#F5C2E0", alt: "Slide 3: pale circle on blush pink" },
  ];
  const dotSize = dotStyle === "line" ? { width: 20, height: 4, borderRadius: 2 } : { width: 8, height: 8, borderRadius: "50%" };
  return (
    <div style={{ maxWidth: 360, font: "13px/1.4 system-ui, sans-serif", color: "#241430", "--accent": accent }}>
      <input className="img-slider-rc__radio" type="radio" name="img-slider-rc-slide" id="img-slider-rc-s1" defaultChecked />
      <input className="img-slider-rc__radio" type="radio" name="img-slider-rc-slide" id="img-slider-rc-s2" />
      <input className="img-slider-rc__radio" type="radio" name="img-slider-rc-slide" id="img-slider-rc-s3" />

      <div className="img-slider-rc__viewport" style={{ position: "relative", overflow: "hidden", border: "1px solid #24143022", borderRadius: radius }}>
        <div className="img-slider-rc__track" style={{ display: "flex", width: "300%" }}>
          {slides.map((s) => (
            <svg key={s.alt} viewBox="0 0 400 260" width="100%" height="100%" style={{ flex: "0 0 33.333%", display: "block" }} role="img" aria-label={s.alt}>
              <rect width="400" height="260" fill={s.fill} />
              <circle cx="200" cy="130" r="70" fill="#FAF7F2" />
            </svg>
          ))}
        </div>
        {showArrows && (
          <div className="img-slider-rc__arrows" style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 8px", pointerEvents: "none" }}>
            <label className="img-slider-rc__arrow img-slider-rc__arrow--for-1" htmlFor="img-slider-rc-s3" aria-label="Previous image">&#8249;</label>
            <label className="img-slider-rc__arrow img-slider-rc__arrow--for-1" htmlFor="img-slider-rc-s2" aria-label="Next image">&#8250;</label>
            <label className="img-slider-rc__arrow img-slider-rc__arrow--for-2" htmlFor="img-slider-rc-s1" aria-label="Previous image">&#8249;</label>
            <label className="img-slider-rc__arrow img-slider-rc__arrow--for-2" htmlFor="img-slider-rc-s3" aria-label="Next image">&#8250;</label>
            <label className="img-slider-rc__arrow img-slider-rc__arrow--for-3" htmlFor="img-slider-rc-s2" aria-label="Previous image">&#8249;</label>
            <label className="img-slider-rc__arrow img-slider-rc__arrow--for-3" htmlFor="img-slider-rc-s1" aria-label="Next image">&#8250;</label>
          </div>
        )}
      </div>

      <div style={{ display: "flex", gap: 8, justifyContent: "center", marginTop: 10 }}>
        <label className="img-slider-rc__dot" htmlFor="img-slider-rc-s1" aria-label="Go to slide 1" style={{ display: "block", cursor: "pointer", background: "#24143033", ...dotSize }} />
        <label className="img-slider-rc__dot" htmlFor="img-slider-rc-s2" aria-label="Go to slide 2" style={{ display: "block", cursor: "pointer", background: "#24143033", ...dotSize }} />
        <label className="img-slider-rc__dot" htmlFor="img-slider-rc-s3" aria-label="Go to slide 3" style={{ display: "block", cursor: "pointer", background: "#24143033", ...dotSize }} />
      </div>

      <style>{`
        .img-slider-rc__radio { position: absolute; opacity: 0; width: 1px; height: 1px; overflow: hidden; }
        @media (prefers-reduced-motion: no-preference) {
.img-slider-rc__track { transition: transform .2s ease; }
}
        #img-slider-rc-s1:checked ~ .img-slider-rc__viewport .img-slider-rc__track { transform: translateX(0%); }
        #img-slider-rc-s2:checked ~ .img-slider-rc__viewport .img-slider-rc__track { transform: translateX(-33.333%); }
        #img-slider-rc-s3:checked ~ .img-slider-rc__viewport .img-slider-rc__track { transform: translateX(-66.666%); }
        .img-slider-rc__arrow { pointer-events: auto; display: none; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 50%; background: #FAF7F2cc; color: #241430; cursor: pointer; font-size: 16px; line-height: 1; text-decoration: none; }
        .img-slider-rc__arrow:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
        #img-slider-rc-s1:checked ~ .img-slider-rc__viewport .img-slider-rc__arrow--for-1 { display: flex; }
        #img-slider-rc-s2:checked ~ .img-slider-rc__viewport .img-slider-rc__arrow--for-2 { display: flex; }
        #img-slider-rc-s3:checked ~ .img-slider-rc__viewport .img-slider-rc__arrow--for-3 { display: flex; }
        .img-slider-rc__dot:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
        #img-slider-rc-s1:checked ~ div label:nth-of-type(1),
        #img-slider-rc-s2:checked ~ div label:nth-of-type(2),
        #img-slider-rc-s3:checked ~ div label:nth-of-type(3) { background: var(--accent); }
      `}</style>
    </div>
  );
}
